"""The frontend decoder is tested against fixtures generated by the backend encoder; they must stay in sync."""

from __future__ import annotations

import importlib.util
from pathlib import Path

SCRIPT = Path(__file__).resolve().parents[1] / "scripts" / "make_fixtures.py"


def test_committed_fixtures_match_the_encoder():
    spec = importlib.util.spec_from_file_location("make_fixtures", SCRIPT)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    for name, data in mod.build().items():
        p = mod.OUT / name
        assert p.exists(), f"missing fixture {name}: run python backend/scripts/make_fixtures.py"
        current = p.read_bytes() if isinstance(data, bytes) else p.read_text()
        assert current == data, f"fixture {name} is stale: run python backend/scripts/make_fixtures.py"
